import { useEffect, useState } from 'react';
import { snapshot, subscribe, type LogEntry } from '../logger';

export function Logs() {
  const [entries, setEntries] = useState<LogEntry[]>(() => snapshot());

  useEffect(() => {
    const unsub = subscribe((e) => setEntries((prev) => [...prev.slice(-499), e]));
    return () => { unsub(); };
  }, []);

  return (
    <div className="logs" role="log" aria-live="polite" aria-label="Logs de ejecución">
      {entries.length === 0
        ? '— sin logs todavía —'
        : entries.map((e, i) => (
            <div key={i}>
              <span className="muted">{new Date(e.ts).toLocaleTimeString()}</span>{' '}
              <strong>[{e.stage}]</strong>{' '}
              <span style={{ color: e.level === 'error' ? 'var(--danger)' : e.level === 'warn' ? 'var(--warn)' : undefined }}>
                {e.message}
              </span>
            </div>
          ))}
    </div>
  );
}
